<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{section:string;request:Request;readonly:boolean;aiReview?:boolean}>();
const busy=ref(false),error=ref(''),notice=ref(''),status=ref<any>({}),runs=ref<any[]>([]),options=ref<any[]>([]),overview=ref<any>({metrics:{},plans:[]}),tenants=ref<any[]>([]),orders=ref<any[]>([]);
const ai=reactive({taskType:'CUSTOMER_SUMMARY',recordId:'',instructions:'',dataApproved:false,confirmationToken:''});
const preview=ref<any>(null),runKey=ref('');
const order=reactive({tenantId:'',planId:'',periodMonths:12,amount:'',dueDate:new Date(Date.now()+14*86400000).toISOString().slice(0,10),notes:''});
const labels:Record<string,string>={CUSTOMER_SUMMARY:'客户经营摘要',OPPORTUNITY_COACH:'商机推进建议',TICKET_REPLY:'客户工单回复'};
const states:Record<string,string>={PENDING:'待发送',RUNNING:'处理中',SUCCEEDED:'已完成',FAILED:'供应商失败',BLOCKED:'未配置供应商',PAID:'已收款',CANCELLED:'已取消',DRAFT:'草稿'};
const configured=computed(()=>status.value.configured&&status.value.planEnabled);
function money(v:number){return '¥'+((v??0)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function date(v:string){return v?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'medium',timeStyle:'short'}).format(new Date(v)):'—';}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function aiOptions(){options.value=[];ai.recordId='';try{if(ai.taskType==='CUSTOMER_SUMMARY'){const r=await props.request('/customers/options?pageSize=100&writable=false');options.value=(r.items??[]).map((x:any)=>({id:x.id,name:x.name}));}else if(ai.taskType==='OPPORTUNITY_COACH'){const r=await props.request('/opportunities?page=1&pageSize=100&q=&stage=');options.value=(r.items??[]).map((x:any)=>({id:x.id,name:`${x.title} · ${x.customerName}`}));}else{const r=await props.request('/tickets?page=1&pageSize=100&q=&status=');options.value=(r.items??[]).map((x:any)=>({id:x.id,name:`${x.ticketNumber} · ${x.title}`}));}ai.recordId=options.value[0]?.id??'';}catch{options.value=[];}}
async function loadAi(){[status.value,runs.value]=await Promise.all([props.request('/ai/status'),props.request('/ai/runs')]);await aiOptions();}
async function prepare(){await run(async()=>{preview.value=await props.request('/ai/preview','POST',{...ai,dataApproved:false,confirmationToken:null});ai.confirmationToken=preview.value.confirmationToken;ai.dataApproved=false;runKey.value=crypto.randomUUID();});}
watch(()=>[ai.taskType,ai.recordId,ai.instructions],()=>{preview.value=null;ai.confirmationToken='';ai.dataApproved=false;runKey.value='';});
async function generate(){await run(async()=>{const r=await props.request('/ai/runs','POST',ai,{'Idempotency-Key':runKey.value});runs.value=await props.request('/ai/runs');status.value=await props.request('/ai/status');notice.value=r.status==='SUCCEEDED'?'AI 建议已生成；请人工核对后使用':r.status==='RUNNING'?'同一请求正在处理中，请刷新调用记录':'本次状态已记录，请查看调用记录；不会重复调用供应商';preview.value=null;ai.confirmationToken='';ai.dataApproved=false;});}
async function feedback(row:any,rating:number){await run(async()=>{await props.request('/ai/runs/'+row.id+'/feedback','PUT',{rating,notes:''});runs.value=await props.request('/ai/runs');notice.value='反馈已保存';});}
async function loadCommercial(){[overview.value,tenants.value,orders.value]=await Promise.all([props.request('/platform/commercial/overview'),props.request('/platform/commercial/tenants'),props.request('/platform/commercial/orders')]);order.tenantId=order.tenantId||tenants.value[0]?.id||'';order.planId=order.planId||overview.value.plans?.[0]?.id||'';}
async function saveEntitlements(plan:any){await run(async()=>{await props.request(`/platform/commercial/plans/${plan.id}/entitlements`,'PATCH',{configurationEnabled:plan.configurationEnabled,portalEnabled:plan.portalEnabled,aiEnabled:plan.aiEnabled,aiMonthlyRunLimit:Number(plan.aiMonthlyRunLimit),expectedVersion:plan.version});await loadCommercial();notice.value='套餐功能权益已更新；企业下一次请求立即按新权益校验';});}
async function createOrder(){await run(async()=>{const amount=order.amount.trim()?Math.round(Number(order.amount)*100):null;if(order.amount.trim()&&(!Number.isFinite(amount)||Number(amount)<0))throw new Error('订单金额无效');await props.request('/platform/commercial/orders','POST',{tenantId:order.tenantId,planId:order.planId,periodMonths:Number(order.periodMonths),amountCents:amount,dueDate:order.dueDate,notes:order.notes},{'Idempotency-Key':crypto.randomUUID()});order.amount='';order.notes='';await loadCommercial();notice.value='人工订阅订单已创建，尚未发生扣款或续期';});}
async function paid(row:any){const reference=prompt('请输入已核实的收款凭据编号')?.trim();if(!reference)return;await run(async()=>{await props.request(`/platform/commercial/orders/${row.id}/mark-paid`,'POST',{externalReference:reference,expectedVersion:row.version});await loadCommercial();notice.value='收款已确认，套餐和订阅期限已更新一次';});}
async function cancel(row:any){const reason=prompt('请输入取消原因')?.trim();if(!reason)return;await run(async()=>{await props.request(`/platform/commercial/orders/${row.id}/cancel`,'POST',{reason,expectedVersion:row.version});await loadCommercial();notice.value='订单已取消并保留审计记录';});}
watch(()=>ai.taskType,()=>run(aiOptions));watch(()=>props.section,()=>run(props.section==='ai-assistant'?loadAi:loadCommercial));onMounted(()=>run(props.section==='ai-assistant'?loadAi:loadCommercial));
</script>

<template>
 <section class="p4c">
  <div class="page-heading"><div><span class="eyebrow">P4 · PRODUCTIZATION</span><h1>{{section==='ai-assistant'?'AI 业务助手':'商业化运营'}}</h1><p>{{section==='ai-assistant'?'在现有权限范围内生成摘要、推进建议和回复草稿；所有调用留痕。':'管理套餐权益、企业用量与人工订阅订单，不自动扣款。'}}</p></div></div>
  <div v-if="error" class="alert bad" role="alert">{{error}}</div><div v-if="notice" class="alert ok" role="status">{{notice}}</div>
  <template v-if="section==='ai-assistant'">
   <section class="summary"><article class="card"><span>供应商状态</span><strong>{{status.configured?'已配置':'未配置'}}</strong><small>{{status.provider||'OPENAI_COMPATIBLE'}} · {{status.model||'等待模型配置'}}</small></article><article class="card"><span>本月调用</span><strong>{{status.monthlyUsed||0}} / {{status.monthlyLimit||0}}</strong><small>含处理中及结果待核定调用；明确失败退回额度</small></article><article class="card"><span>数据边界</span><strong>白名单字段</strong><small>常见联系方式、证件及凭据按规则脱敏；发送前仍需人工核对</small></article></section>
   <div v-if="!status.planEnabled" class="alert warn">当前套餐未启用 AI，请由平台运营调整套餐权益。</div><div v-else-if="!status.configured" class="alert warn">当前 AI 连接尚未就绪。产品方需配置模型和密钥，企业管理员需在左侧“企业 AI 设置”选择模型并启用；未就绪时不会外呼。</div>
   <form class="card form" @submit.prevent="generate"><h2>新建 AI 任务</h2><div class="grid"><label>任务类型<select v-model="ai.taskType" :disabled="busy"><option v-for="(name,key) in labels" :key="key" :value="key">{{name}}</option></select></label><label>业务记录<select v-model="ai.recordId" required :disabled="busy||!options.length"><option v-for="item in options" :key="item.id" :value="item.id">{{item.name}}</option></select><small v-if="!options.length">当前权限范围内没有可选记录</small></label><label class="wide">补充要求（可选）<textarea v-model="ai.instructions" rows="3" maxlength="1000" placeholder="例如：突出下周需要完成的动作"></textarea></label></div><button class="btn secondary" type="button" :disabled="busy||readonly||!ai.recordId" @click="prepare">预览脱敏内容</button><section v-if="preview" class="ai-preview"><h3>本次发送内容</h3><p>{{preview.provider}} / {{preview.model}} · 确认有效期 5 分钟</p><pre>{{preview.promptPreview}}</pre><small>请核对这些内容是否获准发送。模型只生成建议，不执行业务操作。</small></section><label class="check"><input v-model="ai.dataApproved" type="checkbox" :disabled="!preview"/>我已核对上方脱敏内容，同意本次发送给列明的供应商及模型</label><button class="btn primary" :disabled="busy||readonly||!configured||!ai.recordId||!ai.dataApproved||!preview">{{busy?'正在处理…':'生成建议'}}</button></form>
   <section class="card table"><div class="title"><h2>{{aiReview?'企业 AI 调用记录':'我的 AI 调用记录'}}</h2><span>最近 {{runs.length}} 条</span></div><div class="table-scroll"><table><thead><tr><th>时间 / 使用人</th><th>任务 / 状态</th><th>脱敏上下文</th><th>AI 输出</th><th>参考费用 / 反馈</th></tr></thead><tbody><tr v-for="row in runs" :key="row.id"><td>{{date(row.createdAt)}}<small>{{row.memberName}}</small></td><td>{{labels[row.taskType]}}<small><span class="badge" :class="row.status==='SUCCEEDED'?'green':'neutral'">{{states[row.status]||row.status}}</span></small></td><td>{{row.contextPreview}}</td><td><pre>{{row.resultText||row.errorCode||'—'}}</pre></td><td><small>{{money(row.estimatedCostCents)}}{{row.usageEstimated?' · 保守估算':''}}</small><button v-if="row.status==='SUCCEEDED'" class="text-button" :class="{selected:row.rating===1}" @click="feedback(row,1)">有帮助</button><button v-if="row.status==='SUCCEEDED'" class="text-button" :class="{selected:row.rating===-1}" @click="feedback(row,-1)">需改进</button></td></tr><tr v-if="!runs.length"><td colspan="5" class="empty-cell">暂无 AI 调用记录</td></tr></tbody></table></div></section>
  </template>
  <template v-else>
   <section class="summary"><article class="card"><span>有效企业</span><strong>{{overview.metrics?.activeTenants||0}}</strong><small>30 天内到期 {{overview.metrics?.expiringTenants||0}} 家</small></article><article class="card"><span>当前月度经常性收入</span><strong>{{money(overview.metrics?.mrrCents||0)}}</strong><small>按有效企业当前套餐测算</small></article><article class="card"><span>本月人工确认收款</span><strong>{{money(overview.metrics?.paidThisMonthCents||0)}}</strong><small>待处理订单 {{overview.metrics?.pendingOrders||0}} 笔</small></article></section>
   <section class="card form"><div class="title"><div><h2>套餐功能权益</h2><p>控制行业配置、客户门户与 AI 是否可用，并设置每企业每月 AI 成功调用额度。</p></div></div><div class="entitlements"><article v-for="plan in overview.plans" :key="plan.id"><strong>{{plan.name}}</strong><span>{{money(plan.monthlyPriceCents)}} / 月 · {{plan.tenantCount}} 家企业</span><div><label><input v-model="plan.configurationEnabled" type="checkbox"/>行业配置</label><label><input v-model="plan.portalEnabled" type="checkbox"/>客户门户</label><label><input v-model="plan.aiEnabled" type="checkbox"/>AI 助手</label></div><label>AI 月额度<input v-model.number="plan.aiMonthlyRunLimit" type="number" min="0" max="1000000" :disabled="!plan.aiEnabled"/></label><button class="btn secondary" :disabled="busy" @click="saveEntitlements(plan)">保存权益</button></article></div></section>
   <form class="card form" @submit.prevent="createOrder"><div class="title"><div><h2>创建人工订阅订单</h2><p>确认收款前不会改变套餐、订阅期限或产生自动扣款。</p></div></div><div class="grid"><label>客户企业<select v-model="order.tenantId" required><option v-for="t in tenants" :key="t.id" :value="t.id">{{t.name}} · {{t.planName}}</option></select></label><label>目标套餐<select v-model="order.planId" required><option v-for="p in overview.plans" :key="p.id" :value="p.id">{{p.name}} · {{money(p.monthlyPriceCents)}} / 月</option></select></label><label>订阅周期<select v-model.number="order.periodMonths"><option v-for="n in [1,3,6,12,24,36]" :key="n" :value="n">{{n}} 个月</option></select></label><label>订单金额（元，可留空按套餐计算）<input v-model="order.amount" inputmode="decimal" placeholder="留空自动计算"/></label><label>应付日期<input v-model="order.dueDate" type="date" required/></label><label>备注<input v-model="order.notes" maxlength="500"/></label></div><button class="btn primary" :disabled="busy">创建待付款订单</button></form>
   <section class="card table"><div class="title"><h2>企业权益与用量</h2><span>{{tenants.length}} 家</span></div><div class="table-scroll"><table><thead><tr><th>企业 / 套餐</th><th>订阅状态</th><th>成员 / 客户 / 附件</th><th>配置 / 门户 / AI</th><th>本月用量</th></tr></thead><tbody><tr v-for="t in tenants" :key="t.id"><td><strong>{{t.name}}</strong><small>{{t.planName}}</small></td><td>{{t.status}}<small>至 {{date(t.subscriptionEnd)}}</small></td><td>{{t.activeMemberCount}} / {{t.seatLimit}} · {{t.customerCount}} / {{t.customerLimit}}<small>{{Math.round((t.attachmentBytes||0)/1048576)}} / {{Math.round((t.storageLimitBytes||0)/1048576)}} MB</small></td><td>{{t.configurationEnabled?'配置':''}} {{t.portalEnabled?'门户':''}} {{t.aiEnabled?'AI':''}}</td><td>AI {{t.aiRuns}} / {{t.aiMonthlyRunLimit}}<small>有效门户账号 {{t.portalAccounts}}</small></td></tr></tbody></table></div></section>
   <section class="card table"><div class="title"><h2>订阅订单</h2><span>仅人工核实</span></div><div class="table-scroll"><table><thead><tr><th>订单 / 企业</th><th>套餐 / 周期</th><th>金额 / 应付日</th><th>状态 / 凭据</th><th>操作</th></tr></thead><tbody><tr v-for="row in orders" :key="row.id"><td><strong>{{row.orderNumber}}</strong><small>{{row.tenantName}}</small></td><td>{{row.planName}}<small>{{row.periodMonths}} 个月</small></td><td>{{money(row.amountCents)}}<small>{{row.dueDate}}</small></td><td><span class="badge" :class="row.status==='PAID'?'green':row.status==='PENDING'?'amber':'neutral'">{{states[row.status]||row.status}}</span><small>{{row.externalReference||'无收款凭据'}}</small></td><td><button v-if="row.status==='PENDING'" class="text-button" @click="paid(row)">确认收款并续期</button><button v-if="['PENDING','DRAFT'].includes(row.status)" class="text-button danger" @click="cancel(row)">取消</button></td></tr><tr v-if="!orders.length"><td colspan="5" class="empty-cell">暂无订阅订单</td></tr></tbody></table></div></section>
  </template>
 </section>
</template>

<style scoped>
.ai-preview{padding:18px;margin-top:18px;border:1px solid var(--border-color,#354d6a);border-radius:8px}.ai-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:280px;overflow:auto;font:inherit;font-size:12px;line-height:1.8}.ai-preview p,.ai-preview small{font-size:12px;color:var(--text-muted,#92a8c3)}

.p4c{display:flex;flex-direction:column;gap:22px}.alert{padding:14px 18px;border-radius:8px;font-size:13px;line-height:1.8}.alert.bad{background:#fff0f1;border:1px solid #efcfd3;color:#a52836}.alert.ok{background:#eaf5ed;border:1px solid #c9e0d0;color:#286045}.alert.warn{background:#fff7e5;border:1px solid #e9d9ab;color:#765618}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.summary article{padding:24px;display:flex;flex-direction:column;gap:10px}.summary span,.summary small{font-size:12px;color:#65766b}.summary strong{font-size:24px;color:#254c35}.form{padding:25px}.form h2,.title h2{font-size:19px}.title{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:20px}.title p,.title span{font-size:12px;color:#64766a;margin-top:7px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid .wide{grid-column:1/-1}.grid label{display:flex;flex-direction:column;gap:8px;font-size:13px;color:#354e3c}.grid input,.grid select,.grid textarea{padding:11px;border:1px solid #cbd8ce;border-radius:6px;background:white;font-size:14px}.grid small{color:#8b5d23}.check{display:flex;align-items:flex-start;gap:9px;font-size:12px;line-height:1.7;color:#536b5c;margin:20px 0}.check input{margin-top:3px;accent-color:#26784f}.table{overflow:hidden}.table>.title{padding:22px 24px 0}.table td{max-width:350px;vertical-align:top;line-height:1.6}.table td small{display:block;color:#68796e;font-size:12px;margin-top:5px}.table pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;margin:0;max-height:240px;overflow:auto}.text-button.selected{font-weight:700;color:#185f38}.danger{color:#a12b35;margin-left:12px}@media(max-width:800px){.summary,.grid{grid-template-columns:1fr}.grid .wide{grid-column:1}.summary{gap:10px}.form{padding:20px}}
.entitlements{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.entitlements article{border:1px solid #dce6df;border-radius:8px;padding:18px;display:flex;flex-direction:column;gap:12px}.entitlements article>span{font-size:12px;color:#64776a}.entitlements article>div{display:flex;gap:14px;flex-wrap:wrap}.entitlements label{font-size:12px;display:flex;gap:7px;align-items:center;color:#405b49}.entitlements input[type=number]{width:110px;padding:7px;border:1px solid #cbd8ce;border-radius:5px}.entitlements input[type=checkbox]{accent-color:#26784f}@media(max-width:800px){.entitlements{grid-template-columns:1fr}}
</style>
